import {start,base} from './common.mjs';const r=await start();try{const html=await(await fetch(base)).text();const urls=[...html.matchAll(/(?:src|href)="([^"]+\.js)"/g)].map(x=>x[1]);console.log('assets',urls);for(const u of urls.length?urls:['/']){const text=await(await fetch(new URL(u,base))).text();for(const key of ['.net','netdev','netdrops-body','net-counters','tcp_retrans_segs']){const i=text.lastIndexOf(key);console.log(key,i,text.slice(Math.max(0,i-600),i+1000));}}}finally{await r.stop();}
